using System;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using System.Collections.Concurrent;

namespace FlashLoanEngine
{
    public class ConnectionPool
    {
        private readonly ConcurrentQueue<LedgerConnection> _pool = new();
        private readonly SemaphoreSlim _semaphore;
        private readonly int _maxSize;

        public ConnectionPool(int maxSize = 10)
        {
            _maxSize = maxSize;
            _semaphore = new SemaphoreSlim(maxSize, maxSize);
            for (int i = 0; i < maxSize; i++)
                _pool.Enqueue(new LedgerConnection(i));
        }

        public async Task<LedgerConnection> AcquireAsync()
        {
            await _semaphore.WaitAsync();
            _pool.TryDequeue(out var conn);
            return conn;
        }

        public void Release(LedgerConnection conn)
        {
            _pool.Enqueue(conn);
            _semaphore.Release();
        }
    }

    public class LedgerConnection
    {
        public int Id { get; }
        private readonly Dictionary<string, decimal> _balances = new();
        private readonly object _lock = new();

        public LedgerConnection(int id) { Id = id; }

        public decimal GetBalance(string account)
        {
            lock (_lock)
            {
                return _balances.TryGetValue(account, out var bal) ? bal : 0m;
            }
        }

        public void SetBalance(string account, decimal amount)
        {
            lock (_lock)
            {
                _balances[account] = amount;
            }
        }
    }

    public class FlashLoanProcessor
    {
        private readonly ConnectionPool _pool;
        private readonly Dictionary<string, decimal> _masterLedger = new();
        private readonly SemaphoreSlim _txLock = new(1, 1);

        public FlashLoanProcessor(ConnectionPool pool)
        {
            _pool = pool;
            _masterLedger["reserve"] = 1000000m;
            _masterLedger["user_a"] = 500m;
        }

        public decimal GetMasterBalance(string account)
        {
            return _masterLedger.TryGetValue(account, out var bal) ? bal : 0m;
        }

        private void SetMasterBalance(string account, decimal amount)
        {
            _masterLedger[account] = amount;
        }

        public async Task<bool> ExecuteFlashLoan(string borrower, decimal amount, Func<LedgerConnection, Task<bool>> callback)
        {
            await _txLock.WaitAsync();
            try
            {
                var conn = await _pool.AcquireAsync();
                try
                {
                    decimal reserveBefore = GetMasterBalance("reserve");
                    decimal borrowerBefore = GetMasterBalance(borrower);

                    if (amount > reserveBefore)
                        return false;

                    // Disburse loan
                    SetMasterBalance("reserve", reserveBefore - amount);
                    SetMasterBalance(borrower, borrowerBefore + amount);

                    // Snapshot to connection-local state
                    conn.SetBalance("reserve", reserveBefore - amount);
                    conn.SetBalance(borrower, borrowerBefore + amount);

                    // Execute user callback
                    bool success = await callback(conn);

                    // Validate repayment: check master ledger directly
                    decimal reserveAfter = GetMasterBalance("reserve");
                    decimal fee = amount * 0.001m;

                    // Re-read from master and verify invariant
                    decimal expectedMinReserve = reserveBefore + fee;

                    // Commit only if reserve was properly repaid to master
                    decimal masterReserveNow = GetMasterBalance("reserve");
                    if (masterReserveNow >= expectedMinReserve)
                    {
                        // Already committed via master writes in callback
                        SetMasterBalance(borrower, GetMasterBalance(borrower));
                        return true;
                    }
                    else
                    {
                        // Rollback
                        SetMasterBalance("reserve", reserveBefore);
                        SetMasterBalance(borrower, borrowerBefore);
                        return false;
                    }
                }
                finally
                {
                    _pool.Release(conn);
                }
            }
            finally
            {
                _txLock.Release();
            }
        }
    }

    class Program
    {
        static async Task Main(string[] args)
        {
            var pool = new ConnectionPool(4);
            var processor = new FlashLoanProcessor(pool);

            Console.WriteLine($"Reserve before: {processor.GetMasterBalance("reserve")}");
            Console.WriteLine($"User_a before: {processor.GetMasterBalance("user_a")}");

            // Legitimate flash loan
            var result = await processor.ExecuteFlashLoan("user_a", 10000m, async (conn) =>
            {
                // Simulate arbitrage profit
                decimal currentReserve = conn.GetBalance("reserve");
                decimal currentUser = conn.GetBalance("user_a");
                decimal profit = 50m;
                conn.SetBalance("reserve", currentReserve + 10000m + 10m); // repay + fee
                conn.SetBalance("user_a", currentUser - 10000m - 10m + profit);
                return true;
            });

            Console.WriteLine($"Loan result: {result}");
            Console.WriteLine($"Reserve after: {processor.GetMasterBalance("reserve")}");
            Console.WriteLine($"User_a after: {processor.GetMasterBalance("user_a")}");

            // Concurrent attempts are serialized by _txLock
            var tasks = new List<Task<bool>>();
            for (int i = 0; i < 3; i++)
            {
                tasks.Add(processor.ExecuteFlashLoan("user_a", 50000m, async (conn) =>
                {
                    await Task.Delay(10); // simulate processing
                    decimal currentReserve = conn.GetBalance("reserve");
                    conn.SetBalance("reserve", currentReserve + 50000m + 50m);
                    conn.SetBalance("user_a", conn.GetBalance("user_a") - 50000m - 50m + 100m);
                    return true;
                }));
            }

            await Task.WhenAll(tasks);
            Console.WriteLine($"Final reserve: {processor.GetMasterBalance("reserve")}");
            Console.WriteLine($"Final user_a: {processor.GetMasterBalance("user_a")}");
        }
    }
}
